  "  punycodePolicy:       \"reject\" | \"audit\" | \"allow\",",
  "  mixedScriptPolicy:    \"reject\" | \"audit\" | \"allow\",",
  "  specialUsePolicy:     \"reject\" | \"audit\" | \"allow\",",
  "  ipLiteralPolicy:      \"reject\" | \"audit\" | \"allow\",",
