  "  singleLabelPolicy:    \"reject\" | \"audit\" | \"allow\",",
  "  trailingDotPolicy:    \"normalize\" | \"audit\",",
  "  dgaPolicy:            \"reject\" | \"audit\" | \"allow\",",
  "  bidiPolicy:           \"reject\" | \"allow\",          // refused at every profile",
  "  controlPolicy:        \"reject\" | \"allow\",          // refused at every profile",
  "  nullBytePolicy:       \"reject\" | \"allow\",          // refused at every profile",
  "  zeroWidthPolicy:      \"reject\" | \"allow\",          // refused at every profile",
  "  allowedScripts:       [\"latin\", \"cyrillic\", ...],",
  "  dgaEntropyThreshold:  number,                       // bits/char (default 3.8)",
  "  dgaMinLabelLen:       number,                       // floor for DGA check (default 12)",
  "  maxLabelOctets:       number,                       // RFC 1035 §2.3.4 (default 63)",
