  "b.guardDomain.validate(\"exa\\u0430mple.com\", { profile: \"strict\" });",
  "// → ok=false; raw-unicode-label + mixed-script (latin, cyrillic)",
  "",
  "// IPv4 in dotted, octal, hex, and long-decimal forms — all refused.",
  "b.guardDomain.validate(\"192.168.1.1\",       { profile: \"strict\" }); // ipv4-as-domain",
  "b.guardDomain.validate(\"0177.0.0.1\",        { profile: \"strict\" }); // ipv4-as-domain",
  "b.guardDomain.validate(\"0xC0.0xA8.0x01.01\", { profile: \"strict\" }); // ipv4-as-domain",
  "b.guardDomain.validate(\"3232235777\",        { profile: \"strict\" }); // ipv4-as-domain",
  "",
  "// RFC 6761 special-use — refused (LAN / loopback / Tor risk).",
  "b.guardDomain.validate(\"admin.local\",  { profile: \"strict\" }); // special-use",
  "b.guardDomain.validate(\"api.internal\", { profile: \"strict\" }); // special-use",
  "",
  "// Wildcard refused at every profile.",
  "b.guardDomain.validate(\"*.example.com\", { profile: \"permissive\" }); // wildcard",
  "</code></pre>",
  "<h2 id=\"guard-domain-sanitize\">b.guardDomain.sanitize(domain, opts) <a class=\"anchor\" href=\"#guard-domain-sanitize\">#</a></h2>",
  "<pre><code class=\"language-javascript\">{",
  "  profile:           \"strict\" | \"balanced\" | \"permissive\",",
  "  compliancePosture: \"hipaa\" | \"pci-dss\" | \"gdpr\" | \"soc2\",",
  "}</code></pre>",
  "<p>Throws on any high / critical-severity issue (the threat-catalog refuses can't be repaired). On safe input, normalizes to lowercase ASCII and strips a trailing FQDN dot. Returns the normalized form.</p>",
  "<pre><code class=\"language-javascript\">b.guardDomain.sanitize(\"Example.COM.\", { profile: \"strict\" });",
  "// → \"example.com\"",
